head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05012";
scwin.LD_MKT_TP_CD = '1';
scwin.BZ_NEWPRE = 0;
scwin.BZ_ADDPRE = 2;
scwin.BZ_ADDLST = 3;
scwin.CD_NEWPRE = '002';
scwin.form = null;
scwin.w = '375';
scwin.h = '220';
scwin.instCodeWin = null;
scwin.openCodeObj = null;
scwin.openNameObj = null;
scwin.l = undefined;
scwin.t = undefined;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — rowCount

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ===  0); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  1); } }, { id: "btn_ElwSub", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "if_transKind", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "tr_216", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "tr_225", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "tr_234", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "tr_243", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "tr_252", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) === 4); } }, { id: "if_transKind_2", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) !== 4); } }, { id: "tr_264", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) !== 4); } }, { id: "tr_275", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })()) !== 4); } }, { id: "if_rowCount", fn: function(){ return ((dma_pageContext.get("rowCount") ?? "") === 1); } }, { id: "tr_580", fn: function(){ return ((dma_pageContext.get("rowCount") ?? "") === 1); } }, { id: "c_when_576", fn: function(){ return (!(String(((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null ? '' : ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })()))).length === 0) && (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) && typeof ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount === 'function' ? ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount() : ((((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null) ? 0 : (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).length || 0))) > 0); } }, { id: "tr_580", fn: function(){ return (!(String(((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null ? '' : ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })()))).length === 0) && (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) && typeof ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount === 'function' ? ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount() : ((((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null) ? 0 : (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).length || 0))) > 0); } }, { id: "c_otherwise_591", fn: function(){ return (!((!(String(((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null ? '' : ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })()))).length === 0) && (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) && typeof ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount === 'function' ? ((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).getRowCount() : ((((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())) == null) ? 0 : (((dma_readDataVO.get("arrayPack") ?? (() => { throw new Error("unresolved:" + "readDataVO.arrayPack"); })())).length || 0))) > 0))); } }, { id: "btn_Register_4", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  1); } }, { id: "btn_ElwSub_2", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "btn_Register_3", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ===  0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_215", entity: "dlt_readDataVOArrayUly", countIds: [], cells: [{ childId: "ipt_ulyIsuCd", fn: function (v, i) { return String(v("bsAssCd1")); } }, { childId: "ipt_ulyIsuNm", fn: function (v, i) { return String(v("bsAssNm1")); } }, { childId: "ipt_ulyCompstRto", fn: function (v, i) { return String(v("bsAssRt1")); } }, { childId: "ipt_ulyIsuCd_2", fn: function (v, i) { return String(v("bsAssCd2")); } }, { childId: "ipt_ulyIsuNm_2", fn: function (v, i) { return String(v("bsAssNm2")); } }, { childId: "ipt_ulyCompstRto_2", fn: function (v, i) { return String(v("bsAssRt2")); } }, { childId: "ipt_ulyIsuCd_3", fn: function (v, i) { return String(v("bsAssCd3")); } }, { childId: "ipt_ulyIsuNm_3", fn: function (v, i) { return String(v("bsAssNm3")); } }, { childId: "ipt_ulyCompstRto_3", fn: function (v, i) { return String(v("bsAssRt3")); } }, { childId: "ipt_ulyIsuCd_4", fn: function (v, i) { return String(v("bsAssCd4")); } }, { childId: "ipt_ulyIsuNm_4", fn: function (v, i) { return String(v("bsAssNm4")); } }, { childId: "ipt_ulyCompstRto_4", fn: function (v, i) { return String(v("bsAssRt4")); } }, { childId: "ipt_ulyIsuCd_5", fn: function (v, i) { return String(v("bsAssCd5")); } }, { childId: "ipt_ulyIsuNm_5", fn: function (v, i) { return String(v("bsAssNm5")); } }, { childId: "ipt_ulyCompstRto_5", fn: function (v, i) { return String(v("bsAssRt5")); } }] },
        { genId: "c_foreach_263", entity: "dlt_readDataVOArrayUly", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "주권발행기관_" + String(i + 1); } }, { childId: "ipt_ulyIsuCd_6", fn: function (v, i) { return String(v("ulyIsuCd")); } }, { childId: "ipt_ulyIsuNm_6", fn: function (v, i) { return String(v("ulyIsuNm")); } }, { childId: "ipt_ulyCompstRto_6", fn: function (v, i) { return String(v("ulyCompstRto")); } }] },
        { genId: "c_foreach_578", entity: "dlt_readDataVOArrayPack", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(i + 1); } }, { childId: "ipt_byelwPackDeclSeq", fn: function (v, i) { return String(i + 1); } }, { childId: "ipt_isuYymm", fn: function (v, i) { return String(v("isuYymm")); } }, { childId: "ipt_isuSchdlAmt", fn: function (v, i) { return String(v("isuSchdlAmt")); } }, { childId: "ipt_isuPrfmAmt", fn: function (v, i) { return String(v("isuPrfmAmt")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_isuTotSum", fn: function () { return String((String(dma_readDataVO.get("isuShrs")) * String(dma_readDataVO.get("isuPrc")))); } },
        { childId: "ipt_isuDd1", fn: function () { return String(String(dma_readDataVO.get("isuDd")).substring(0, 6)); } },
        { childId: "ipt_isuDd2", fn: function () { return String(String(dma_readDataVO.get("isuDd")).substring(6, 8)); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent("dma_RegisterReq").set("bzCd", scwin.BZ_NEWPRE);
        $c.util.getComponent("dma_RegisterReq").set("listBzTpCd", scwin.CD_NEWPRE);
        $c.util.getComponent("dma_RegisterReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        /* 수동 전환 필요: transTbl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[1].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[2].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[3].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        $c.util.getComponent('ipt_isuShtNm').setValue($c.util.getComponent("dma_RegisterReq").get("isuAbbrv1") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv2") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv3") + $c.util.getComponent("dma_RegisterReq").get("isuAbbrv4"));
        $c.util.getComponent('ipt_engIsuShtNm').setValue($c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv1") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv2") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv3") + $c.util.getComponent("dma_RegisterReq").get("isuEngAbbrv4"));
        scwin.commaValueAll();
        scwin.setSelectDisabled(true);
        scwin.setElwKoValuPrcMethd();
        setElwExerContn();
        setElwKoExerContn();
        setElwKoBasPrc();
        setElwExpValuPrcMethd($c.util.getComponent('ipt_elwExpValuPrcMethd').getValue());
        setElwCompnsRt();
        setIsuExp();
        if ($c.util.getComponent('slc_fncUlyTpCd').getValue()=== 2) {
            for (let i = 0; i < $c.util.getComponent('ipt_ulyIsuCd').length; i++) {
                $c.util.getComponent(["ipt_ulyCompstRto", "ipt_ulyCompstRto_2", "ipt_ulyCompstRto_3", "ipt_ulyCompstRto_4", "ipt_ulyCompstRto_5", "ipt_ulyCompstRto_6", "ipt_ulyCompstRto_7"][i]).readOnly = false;
            }
        } else {
            if ($c.util.getComponent('slc_fncUlyTpCd').getValue()=== 3) {

            }
        }
        if ($c.util.getComponent('ipt_elwFinalPayVal').getValue()=== 0) {
            $c.util.getComponent('ipt_elwFinalPayVal').setValue("");
        }
        await (async () => { const m = $c.util.getComponent("dma_readDataVO"); const v = (m && m.get) ? m.get("resultMsg") : ""; if (v) { await $c.win.alert(String(v)); } })();
        if (($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd')) === 0) {
            if ($c.util.getComponent('slc_elwObjIdxTpCd').getValue()=== '6') {
                $c.util.getComponent('slc_idxCalcInstNm').setSelectedIndex(1);
                $c.util.getComponent('slc_trdMktNm').setSelectedIndex(1);
            } else {
                if ($c.util.getComponent('slc_elwObjIdxTpCd').getValue()=== '7') {
                    $c.util.getComponent('slc_idxCalcInstNm').setSelectedIndex(2);
                    $c.util.getComponent('slc_trdMktNm').setSelectedIndex(2);
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05012.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_ElwForm = { action: "", method: 'post', target: '' };

try { scwin.l =screen.width/2 - scwin.w/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05012' }); }

try { scwin.t =screen.height/2 - scwin.h/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05012' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05012.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
