/**
 * @method
 * @name btn_ElwPageSearch_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPageSearch_onclick = async function(e){
    try {
        await scwin.elwPageSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05012.btn_ElwPageSearch_onclick' }); }
