/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.issSchdCheckValues2()) {
        return;
    }
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!scwin.vailidationLn()) {
        return;
    }
    if (!fn_IsValidDate(scwin.form, CheckDateArrVar)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsValidDate — 폼·DOM 의존(B-7)
        return;
    }
    if (!await scwin.isValid(scwin.form, CheckArrVar)) {
        return;
    }
    if (!fn_chkSaveElwPrc()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_chkSaveElwPrc — 폼·DOM 의존(B-7)
        return;
    }
    if (!fn_IsuCheckValues()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsuCheckValues — as-is 공통(폼 전역 의존) — 반입 보류
        return;
    }
    if (!fn_checkElwKoBasPrc()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_checkElwKoBasPrc — as-is 공통(폼 전역 의존) — 반입 보류
        return;
    }
    if (!fn_checkElwCompnsRt()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_checkElwCompnsRt — as-is 공통(폼 전역 의존) — 반입 보류
        return;
    }
    if (!fn_checkIsuExp()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_checkIsuExp — as-is 공통(폼 전역 의존) — 반입 보류
        return;
    }
    if (!fn_checkElwKoExerContn()) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_checkElwKoExerContn — as-is 공통(폼 전역 의존) — 반입 보류
        return;
    }
    scwin.setSelectDisabled(false);
    if (!fn_IsValidSelect(scwin.form, CheckSelArrVar, CheckSelArrVarAlt)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsValidSelect — as-is 공통(폼 전역 의존) — 반입 보류
        scwin.setSelectDisabled(true);
        return;
    }
    if (!await $c.fil.confirmJob('I')) {
        return;
    }
    scwin.rmCommaValueAll();
    scwin.rmCommaValueAllForKO();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
};

