/**
 * @method
 * @name checkDate2
 * @description check Date2 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDate2 = async function (obj) {
    const f = (document.ElwForm || { elements: [] });
    $c.util.getComponent('dma_RegisterReq').set('isuDd', $c.util.getComponent('ipt_isuDd1').getValue()+ $c.util.getComponent('ipt_isuDd2').getValue());
    obj = f.isuDd;
    if (obj.value.length === 0) {
        return true;
    }
    obj.value = $c.str.replaceAll(obj.value, '-', "");
    obj.value = $c.str.replaceAll(obj.value, '/', "");
    if (obj.value.length !== 8) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날짜는 8 자리 YYYYMMDD 형식입니다.');
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    if (obj.value !== '' && !$c.fil.isMinusNumber(obj.value)) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + "숫자만 입력가능합니다.");
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    const year = obj.value.substring(0, 4);
    const month = obj.value.substring(4, 6);
    const day = obj.value.substring(6, 8);
    if (month > 12 || month < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '달은 1 에서 12 사이여야 합니다.');
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    if (day > 31 || day < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날은 1 에서 31 사이여야 합니다.');
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    return true;
};

