    } else {
        if (($c.util.getComponent("dma_RegisterReq").get("isuYymm") == null ? '' : String($c.util.getComponent("dma_RegisterReq").get("isuYymm"))) !== '') {
            if ($c.util.getComponent("dma_RegisterReq").get("isuYymm").length > 4) {
