 */
scwin.Chk_Sosu_Point_Final_Pay_Amt = async function (Name) {
    const sVal = $c.str.replaceAll(Name.getValue(), ",", "");
    if (!Chk_Digit_Point(sVal)) {
        await $c.win.alert(" 숫자와 . 만 입력 가능합니다.");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sVal >= 100000) {
        await $c.win.alert("만원단위까지 입력이 가능합니다.");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    return true;
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};

